python -c "
import sys, json, subprocess, os
from pathlib import Path
data = json.load(sys.stdin)
fp = data.get('tool_input', {}).get('file_path', '')
if not fp.endswith('.py'): sys.exit(0)
p = Path(fp) if Path(fp).is_absolute() else Path(os.getcwd()) / fp
root = p.parent
while root != root.parent:
    if (root / 'pyproject.toml').exists() or (root / 'pytest.ini').exists(): break
    root = root.parent
else: sys.exit(0)
tests_dir = root / 'tests'
if not tests_dir.exists(): sys.exit(0)
stem = p.stem
if stem.startswith('test_'):
    targets = [str(p)]
else:
    matches = list(tests_dir.glob(f'test_{stem}.py')) + list(tests_dir.glob(f'test_*{stem}*.py'))
    seen = set(); targets = []
    for m in matches:
        r = str(m.resolve())
        if r not in seen: seen.add(r); targets.append(str(m))
    if not targets: sys.exit(0)
result = subprocess.run(['python', '-m', 'pytest', '--tb=short', '-q'] + targets, cwd=str(root), capture_output=True, text=True)
out = (result.stdout or '') + (result.stderr[-300:] if result.stderr else '')
if result.returncode != 0: print(out[-2000:])
sys.exit(result.returncode)
"
